#!/usr/bin/env bash
# Tests of the adjoints generated by Rust's Enzyme-based autodiff (cargo
# feature `enzyme` of lightsim-core): the chi2/chi3 and dispersive-pole cell
# updates against the hand-written adjoints, and the CPU reverse pass using
# the generated ones.
#
# The pinned stable toolchain cannot build this feature. It needs a nightly
# toolchain with the Enzyme component:
#
#   rustup toolchain install nightly --profile minimal --component enzyme-preview
#
# plus `-Zautodiff=Enable` and fat LTO, which this script sets. Nothing else
# in the project uses nightly; the kernels and the default build stay on the
# pinned toolchain. LIGHTSIM_ENZYME_TOOLCHAIN selects another toolchain name.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
TC="${LIGHTSIM_ENZYME_TOOLCHAIN:-nightly}"
CARGO_BIN="$(rustup which --toolchain "$TC" cargo)"
export PATH="$(dirname "$CARGO_BIN"):$PATH"
export RUSTUP_TOOLCHAIN="$TC"
export RUSTFLAGS="-Zautodiff=Enable ${RUSTFLAGS:-}"
export CARGO_PROFILE_TEST_LTO=fat
cd "$ROOT"
# unit tests only: built as a dependency the crate aborts inside Enzyme on
# this nightly (see crates/lightsim-core/src/autodiff/enzyme.rs)
"$CARGO_BIN" test -p lightsim-core --features enzyme --target-dir "$ROOT/target/enzyme" --lib autodiff -- --nocapture
